[12 Regression] Incorrect code emitted when using "constexpr std::array" sincer8-3497-g281e6c1d8f1b4c
Considering:

#include <algorithm>
#include <array>
#include <iostream>
#include <span>
#include <utility>

auto f(int const n) {
    using s_t = std::pair<int, int>;

#if defined(WITH_CONST)
    const
#else
    // gcc 14 emits incorrect code with "constexpr"
    constexpr
#endif
        std::array a_vec{s_t{1, 123}};

    auto const vec{[&a_vec]() -> std::span<s_t const> { return a_vec; }()};

    {
        auto const it = std::ranges::find_if(vec, [n](auto const& v) {
            std::cout << v.first << ", " << v.second << '\n';
            return n >= v.first;
        });
        if (it != std::ranges::end(vec)) {
            return it->second;
        }
    }
    return -1;
}

int main() {
    auto const r = f(1);
    std::cout << "Found=" << r << " expected=123\n";
}


